import networkx as nx

def find_cycle(G):
    visited = set()
    parent = {}
    for node in G.nodes():
        if node not in visited:
            if dfs_cycle(G, node, visited, parent):
                return True, get_cycle_path(parent, node)
    return False, []

def dfs_cycle(G, node, visited, parent):
    visited.add(node)
    for neighbor in G.neighbors(node):
        if neighbor not in visited:
            parent[neighbor] = node
            if dfs_cycle(G, neighbor, visited, parent):
                return True
        elif neighbor != parent[node]:
            # Found a back edge, cycle detected
            cycle = []
            curr = node
            while curr != neighbor:
                cycle.append(curr)
                curr = parent[curr]
            cycle.append(neighbor)
            return True
    return False

def get_cycle_path(parent, start):
    cycle = []
    curr = start
    while True:
        cycle.append(curr)
        if curr == start:
            break
        curr = parent[curr]
    return cycle
